const KCAL_PER_KJ = 1 / 4.184;

function normalizeSimple(name, units, s) {
  let metric = name, value = s.qty, unit = units;
  if (metric === 'active_energy' || metric === 'basal_energy_burned') {
    if (units === 'kJ') { value = value * KCAL_PER_KJ; unit = 'kcal'; }
    metric = metric === 'active_energy' ? 'active_energy_kcal' : 'basal_energy_kcal';
  }
  return [{ metric, source: s.source || null, start_ts: s.date, end_ts: null, value, unit, raw: s }];
}
function normalizeHeartRate(units, s) {
  return [{ metric: 'heart_rate', source: s.source || null, start_ts: s.date, end_ts: null, value: s.Avg, unit: units, raw: s }];
}
function normalizeSleep(s) {
  return [
    ['sleep_total_hours',  s.totalSleep],
    ['sleep_core_hours',   s.core],
    ['sleep_deep_hours',   s.deep],
    ['sleep_rem_hours',    s.rem],
    ['sleep_awake_hours',  s.awake],
    ['sleep_in_bed_hours', s.inBed],
  ].filter(([, v]) => v != null).map(([metric, value]) => ({
    metric, source: s.source || null, start_ts: s.date, end_ts: null, value, unit: 'h', raw: s
  }));
}
function normalizeMetric(m) {
  const ss = m.data || [];
  if (m.name === 'heart_rate')    return ss.flatMap(x => normalizeHeartRate(m.units, x));
  if (m.name === 'sleep_analysis') return ss.flatMap(x => normalizeSleep(x));
  return ss.flatMap(x => normalizeSimple(m.name, m.units, x));
}

const out = [];
for (const item of $input.all()) {
  const metrics = (item.json && item.json.parsed && item.json.parsed.data && item.json.parsed.data.metrics) || [];
  for (const m of metrics) out.push(...normalizeMetric(m));
}
return out.map(json => ({ json }));

