  const ts  = v => v == null ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'::timestamptz";
  const json = v => v == null ? 'NULL' : "'" + JSON.stringify(v).replace(/'/g, "''") + "'::jsonb";
  return "INSERT INTO paperclip_health.health_samples " +
    "(metric, source, start_ts, end_ts, value, unit, raw) VALUES (" +
    esc($json.metric) + ', ' + esc($json.source) + ', ' +
    ts($json.start_ts) + ', ' + ts($json.end_ts) + ', ' +
    num($json.value) + ', ' + esc($json.unit) + ', ' +
    json($json.raw) +
    ") ON CONFLICT (metric, source, start_ts) DO NOTHING;";
})() }}

